namespace {
struct Panel {uint64_t slot,source,target,chart,index,slab,free_child;int32_t eta_index,eta_count;S u0,u1,eta0,eta1;};
struct Axis {uint64_t slot,index,axis,passed;S u,eta,v,s,t,width,J,reference_radius,reference_measure,argument;Q contraction,invariance,forcing,radius,prior,argument_limit;int32_t argument_phase,argument_edge;char reason[192];};
struct Plan {Frame29 frame;op::Linear linear;std::vector<os::Slab>slabs;std::vector<Panel>panel;std::vector<Axis>axis;bool planned=false,clear=false;Q source_radius=0,scale=0;std::string reason;};
static void plan(const curved::Packet&p,const sd::Compiled&m,const std::vector<target::Face>&faces,Plan&w,uint64_t cap){auto shape=target::shape_bounds(m);Q r2=0;for(int k=0;k<2;k++){Q lo=sf::lower(m.base.vertex[0][k]),hi=sf::upper(m.base.vertex[0][k]);for(int a=1;a<3;a++){lo=std::min(lo,sf::lower(m.base.vertex[a][k]));hi=std::max(hi,sf::upper(m.base.vertex[a][k]));}Q d=lo>0?lo:hi<0?-hi:Q(0);r2=mf::FP<Q>::down(r2+mf::FP<Q>::down(d*d));}need(r2>0,"oblique original source excludes reference density origin");w.source_radius=sf::lower(mf::root(S(r2)));w.scale=std::min(w.source_radius,Q(p.parameters[3]))/Q(8);const auto&f=w.frame;Q E=std::max(sf::mag(f.transverse[0]),sf::mag(f.transverse[1])),D=std::max(sf::mag(f.direction[0]),sf::mag(f.direction[1]));
 for(const auto&s:w.slabs)if(!s.empty){need(sf::lower(s.u0)>0||sf::upper(s.u1)<0,"current nonempty oblique slab excludes apex projection u=0");Q metric=E;for(int face:{int(s.lower),int(s.upper)})if(face>=0){auto cone=target::gradient_cone(faces[face],shape);S numerator;for(int k=0;k<2;k++)numerator=numerator+cone.gradient[k]*f.transverse[k];S denominator=f.derivative[face];Q sep=sf::lower(denominator)>0?sf::lower(denominator):-sf::upper(denominator);need(sep>0,"same selected real transverse derivative");metric=std::max(metric,sf::add(E,sf::mul(D,sf::quotient(sf::mag(numerator),sep))));}S full=sf::range(sf::lower(s.u0),sf::upper(s.u1)),lo=os::edge_v(f,s.geometric_lower,full),hi=os::edge_v(f,s.geometric_upper,full);Q dependent=sf::mul(D,sf::mag(hi-lo));int neta=std::max(16,int(ceilq(dependent/w.scale)));need(neta>0&&uint64_t(neta)<=cap/256,"fixed oblique eta metric within authorized plan capacity");Q max_step=mf::FP<Q>::down(w.scale/metric);S left=s.u0;uint64_t child=0;
  while(left.n<s.u1.n){Q distance=sf::lower(left)>0?sf::lower(left):-sf::upper(left);need(distance>0,"positive original oblique apex-projection distance");Q step=std::min(max_step,mf::FP<Q>::down(distance/Q(3))),next=mf::FP<Q>::down(left.n+step);bool last=next>=sf::lower(s.u1);S right=last?s.u1:S(next);need(sf::lower(right)>sf::upper(left),"separated saved event and deterministic oblique panel boundaries");for(int j=0;j<neta;j++){need(w.panel.size()<cap/256,"authorized oblique chart candidate panel budget");Panel b={};b.slot=f.slot;b.source=f.source;b.target=f.target;b.chart=f.chart;b.index=w.panel.size();b.slab=s.index;b.free_child=child;b.eta_index=j;b.eta_count=neta;b.u0=left;b.u1=right;b.eta0=S(j)/S(neta);b.eta1=S(j+1)/S(neta);w.panel.push_back(b);}child++;if(last)break;left=right;}
 }w.planned=true;
}
static void check(const curved::Packet&p,const sd::Compiled&m,const std::vector<target::Face>&faces,Plan&w){uint64_t cached_slab=UINT64_MAX,cached_child=UINT64_MAX;op::Branches branches[2];bool ready[2]={false,false};for(const auto&b:w.panel){auto it=std::find_if(w.slabs.begin(),w.slabs.end(),[&](const os::Slab&s){return s.index==b.slab;});need(it!=w.slabs.end()&&!it->empty,"same actual nonempty slab ID");for(int a=0;a<2;a++){Axis z={};z.slot=b.slot;z.index=b.index;z.axis=a;S u=a?sf::range(0,1):S(Q(.5L),Q(1.25L)),eta=a?S(Q(.5L),Q(1.25L)):sf::range(0,1);z.u=b.u0+(b.u1-b.u0)*u;z.eta=b.eta0+(b.eta1-b.eta0)*eta;bool pass=false;
   try{if(cached_slab!=b.slab||cached_child!=b.free_child){cached_slab=b.slab;cached_child=b.free_child;ready[0]=ready[1]=false;}if(!ready[a]){branches[a]=op::prepare(m,faces,w.frame,w.linear,*it,z.u);ready[a]=true;}auto q=op::point(m,w.frame,w.linear,z.u,z.eta,branches[a]);z.v=q.v;z.s=q.s;z.t=q.t;z.width=q.width;z.J=q.value.field.J;z.contraction=q.contraction;z.invariance=q.invariance;z.forcing=q.forcing;z.radius=q.radius;z.prior=q.prior;z.reference_measure=w.frame.determinant*q.width*(b.u1-b.u0)*(b.eta1-b.eta0);z.reference_radius=target::reference_radius(m,w.frame.original,q.s,q.t,q.value);(void)target::complex_density_bound(p,z.reference_radius);pass=true;snprintf(z.reason,sizeof(z.reason),"original_field_geometry_density_and_oblique_implicit_clearance_pass");}
   catch(const target::GraphFailure&e){snprintf(z.reason,sizeof(z.reason),"%s",e.what());z.contraction=e.contraction;z.invariance=e.invariance;z.forcing=e.forcing;z.radius=e.radius;z.prior=e.prior;}
   catch(const sd::DomainFailure&e){snprintf(z.reason,sizeof(z.reason),"%s",e.what());z.argument=e.argument;z.argument_limit=e.limit;z.argument_phase=e.phase;z.argument_edge=e.edge;}
   catch(const std::exception&e){snprintf(z.reason,sizeof(z.reason),"%s",e.what());}
   z.passed=pass;w.axis.push_back(z);if(!pass){w.reason=z.reason;return;}
  }}w.clear=true;w.reason="all_actual_oblique_candidate_axis_boxes_geometry_density_clearance_pass_no_all12_remainder";}
}
