 need(argc==9&&ranks==1,"packet saved sites weights complete_referencepacket arrangements NEWdest cap");auto begin=std::chrono::steady_clock::now();auto p=curved::read(argv[1]);const auto f=load_saved(std::string(argv[2])+"/shared_state.bin",p);auto before=f.coefficient;auto site=sites(argv[3],argv[4]);std::sort(site.begin(),site.end(),[](const Site&a,const Site&b){return a.id<b.id;});std::string previous=argv[5],arrangements=argv[6],dest=argv[7];uint64_t cap=std::stoull(argv[8]);need(cap==13074432,"approved fixed16x query policy");auto frames=read29<Frame29>(previous+"/oblique_coordinate_frames_rank0.bin");auto slabs=read29<os::Slab>(arrangements+"/actual_oblique_slabs_rank0.bin");need(frames.size()==14&&slabs.size()==98,"adopted14frame/98slab arrangement");std::map<int,sd::Compiled>maps;for(const auto&f0:frames)if(!maps.count(f0.source))maps.emplace(f0.source,sd::compile(f,f0.source));std::vector<Plan>work(frames.size());
