 for(size_t j=0;j<frames.size();j++){auto&w=work[j];w.frame=frames[j];try{const auto&m=maps.at(w.frame.source);w.linear=op::linear(m,w.frame);for(const auto&s:slabs)if(s.slot==w.frame.slot)w.slabs.push_back(s);std::vector<target::Face>faces;for(const auto&p0:target::planes(site,w.frame.target))faces.push_back(target::pullback(m,p0));plan(p,m,faces,w,cap);check(p,m,faces,w);}catch(const std::exception&e){w.reason=e.what();}}
