 for(const auto&w:work){plans+=w.planned;clear+=w.clear;linear.push_back(w.linear);append(panels,w.panel);append(axes,w.axis);ledger<<w.frame.slot<<','<<w.frame.source<<','<<w.frame.target<<','<<w.frame.chart<<','<<w.planned<<','<<w.clear<<','<<w.panel.size()<<','<<(w.planned?std::to_string(w.panel.size()*256):"UNKNOWN")<<','<<w.axis.size()<<','<<qs(w.source_radius)<<','<<qs(w.scale)<<','<<w.reason<<'\n';for(const auto&a:w.axis){passed+=a.passed;acsv<<a.slot<<','<<a.index<<','<<a.axis<<','<<a.passed;for(S z:{a.u,a.eta})acsv<<','<<qs(z.n)<<','<<qs(z.e);for(Q q:{a.contraction,a.invariance,a.forcing,a.radius,a.prior})acsv<<','<<qs(q);acsv<<','<<qs(a.argument.n)<<','<<qs(a.argument.e)<<','<<a.reason<<'\n';}}
 ledger.close();acsv.close();packet(dest+"/candidate_oblique_panels_rank0.bin",panels,0);packet(dest+"/candidate_axis_proofs_rank0.bin",axes,0);packet(dest+"/same_chart_linear_coordinates_rank0.bin",linear,0);packet(dest+"/unchanged_oblique_frames_rank0.bin",frames,0);packet(dest+"/unchanged_actual_slabs_rank0.bin",slabs,0);need(!memcmp(before.data(),f.coefficient.data(),before.size()*sizeof(STCoefficient)),"same original physical state and heat");printf("{\"scope\":\"40 adopted nonempty oblique strips: one fixed original-order actual typed plan and first geometry/density complex-axis clearance prefix per14 failed charts; no all12remainders\",\"completed_candidate_plans\":%llu,\"completed_oblique_chart_geometry_density_clearance\":%llu,\"candidate_panels\":%zu,\"new_complex_axis_evaluations\":%zu,\"new_complex_axis_passes\":%llu,\"authorized_target_query_limit\":%llu,\"OMP_threads\":%d,\"new_inverse_solves\":0,\"new_canonical_root_jobs\":0,\"normal_field_or_panel_replays\":0,\"new_physical_quadrature_queries\":0,\"remaining_incomplete_atlas_slots\":29,\"all12_analytic_remainders_complete\":false,\"all_target_actual_atlas_complete\":false,\"full_quadrature_allowed\":false,\"state_unchanged\":true,\"seconds\":%.17g}\n",(unsigned long long)plans,(unsigned long long)clear,panels.size(),axes.size(),(unsigned long long)passed,(unsigned long long)cap,omp_get_max_threads(),std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count());
